using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class VFXSpawner : ScriptableObject
{
	[Header("VFX")]
	[SerializeField]
	protected bool enableVFX;

	[SerializeField]
	[ShowIf("enableVFX")]
	private GameObject vfxPrefab;

	[SerializeField]
	private bool enableSecondVFX;

	[SerializeField]
	[ShowIf("enableSecondVFX")]
	private GameObject secondVfxPrefab;

	[SerializeField]
	private bool enableThirdVFX;

	[SerializeField]
	[ShowIf("enableThirdVFX")]
	private GameObject thirdVfxPrefab;

	public GameObject VfxPrefab => vfxPrefab;

	public GameObject GetVFX(float storeDelay = 0f)
	{
		return ReferenceSingleton<VFXHandler>.Instance.GetVFX(vfxPrefab, storeDelay);
	}

	public GameObject GetVFX(Vector3 position, float storeDelay = 0f)
	{
		return ReferenceSingleton<VFXHandler>.Instance.GetVFX(vfxPrefab, position, storeDelay);
	}

	public void SpawnVFX(Vector3 position, float storeDelay = 0f)
	{
		if (enableVFX)
		{
			ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(vfxPrefab, position, storeDelay);
		}
	}

	public void SpawnVFX(float storeDelay = 0f)
	{
		if (enableVFX)
		{
			ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(vfxPrefab, storeDelay);
		}
	}

	public void SpawnVFXOnPlayerPosition(float storeDelay = 0f)
	{
		SpawnVFX(GetVFXOwnerPosition(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject), storeDelay);
	}

	public bool IsVFXEnabled()
	{
		if (enableVFX)
		{
			return ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled();
		}
		return false;
	}

	public GameObject GetSecondVFX(float storeDelay = 0f)
	{
		return ReferenceSingleton<VFXHandler>.Instance.GetVFX(secondVfxPrefab, storeDelay);
	}

	public GameObject GetSecondVFX(Vector3 position, float storeDelay = 0f)
	{
		return ReferenceSingleton<VFXHandler>.Instance.GetVFX(secondVfxPrefab, position, storeDelay);
	}

	public void SpawnSecondVFX(Vector3 position, float storeDelay = 0f)
	{
		if (enableSecondVFX)
		{
			ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(secondVfxPrefab, position, storeDelay);
		}
	}

	public void SpawnSecondVFX(float storeDelay = 0f)
	{
		if (enableSecondVFX)
		{
			ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(secondVfxPrefab, storeDelay);
		}
	}

	public void SpawnSecondVFXOnPlayerPosition(float storeDelay = 0f)
	{
		SpawnSecondVFX(GetVFXOwnerPosition(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject), storeDelay);
	}

	public bool IsSecondVFXEnabled()
	{
		if (enableSecondVFX)
		{
			return ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled();
		}
		return false;
	}

	public GameObject GetThirdVFX(float storeDelay = 0f)
	{
		return ReferenceSingleton<VFXHandler>.Instance.GetVFX(thirdVfxPrefab, storeDelay);
	}

	public GameObject GetThirdVFX(Vector3 position, float storeDelay = 0f)
	{
		return ReferenceSingleton<VFXHandler>.Instance.GetVFX(thirdVfxPrefab, position, storeDelay);
	}

	public void SpawnThirdVFX(Vector3 position, float storeDelay = 0f)
	{
		if (enableThirdVFX)
		{
			ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(thirdVfxPrefab, position, storeDelay);
		}
	}

	public void SpawnThirdVFX(float storeDelay = 0f)
	{
		if (enableThirdVFX)
		{
			ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(thirdVfxPrefab, storeDelay);
		}
	}

	public bool IsThirdVFXEnabled()
	{
		if (enableThirdVFX)
		{
			return ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled();
		}
		return false;
	}

	public Vector3 GetVFXOwnerPosition(GameObject VFXOwner)
	{
		if (VFXOwner == ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject)
		{
			return VFXOwner.transform.position.SetZ(80f) + Vector3.up * -0.3f;
		}
		return VFXOwner.transform.position.SetZ(80f);
	}
}
